entries[335235] = { ["name"] = "Höllenbestie beschwören", ["text"] = "2% von Grundmana 100 Meter Reichweite\nSofort\nBeschwört eine Höllenbestie aus dem Wirbelnden Nether, die beim Einschlag (60% der Zaubermacht) Feuerschaden verursacht und alle Gegner im Effektbereich für 2 Sek. betäubt.\n\nDie Höllenbestie steht 30 Sek. lang unter Eurem Befehl, fügt allen Gegnern in der Nähe alle 2 Sek. [(55% der Zaubermacht) * (111) / 100] Schaden zu und erzeugt alle 1 Sek. 1 Seelensplitterfragment." }
entries[335236] = { ["name"] = "Höllenbestie beschwören", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört eine Höllenbestie aus dem Wirbelnden Nether, die beim Einschlag (60% der Zaubermacht) Feuerschaden verursacht und alle Gegner im Effektbereich für 2 Sek. betäubt.\n\nDie Höllenbestie steht 30 Sek. lang unter Eurem Befehl, fügt allen Gegnern in der Nähe alle 2 Sek. [(55% der Zaubermacht) * 111 / 100] Schaden zu und erzeugt alle 1 Sek. 1 Seelensplitterfragment." }
