entries[335470] = { ["name"] = "Kettenschmettern", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchlickfaust macht einen Spielercharakter mit robusten Ketten bewegungsunfähig.\n\nNach 4 Sek. zieht er diesen Spielercharakter und Verbündete innerhalb von 7 Metern zu sich hin und fügt ihnen 115549 körperlichen Schaden zu, der gleichmäßig auf die betroffenen Spielercharaktere aufgeteilt wird." }
