entries[335576] = { ["name"] = "Leitstern des Aufgestiegenen", ["text"] = "Sofort\nCa. 3 Procs pro Minute\nSolange Eure Gesundheit über 90% liegt, haben Eure Schadenszauber und -fähigkeiten eine Chance, Euer Ziel mit 'Zur Einziehung markiert' zu belegen und ihm so 5 Sek. lang alle 1 Sek. [Angriffskraft * 0.55 * (1 + Vielseitigkeit)] Schaden zuzufügen. Wenn Ihr den Gegner während dieser Zeit besiegt, zieht Ihr seine Anima ein, was Euch 10 Sek. lang einen Schild in Höhe von 10% Eurer maximalen Gesundheit gewährt." }
entries[335577] = { ["name"] = "Wache der Weisen", ["text"] = "Sofort\nWenn Eure Gesundheit unter 30% fällt, heilt ein Aufgestiegener Euch vollständig, fügt Gegnern in der Nähe Schaden zu und stößt sie zurück. Ihr erleidet 100% weniger Schaden und dieser Effekt nimmt im Verlauf von 10 Sek. rapide ab. Kann nur einmal alle 3 Min. auftreten." }
entries[335578] = { ["name"] = "Vesperglocke der Klarheit", ["text"] = "Sofort\nWenn Ihr 4 oder mehr Gegner versammelt, haben Eure Schadenszauber und -fähigkeiten eine Chance, für 20 Sek. die Vesperglocke der Klarheit zu beschwören. Die Vesperglocke der Klarheit betäubt Gegner in der Nähe für 5 Sek., wenn sie erscheint, und erhöht Euren verursachten Schaden um 15%, solange Ihr in ihrer Nähe seid.\n(Procchance: 30%, 1Min. Abklingzeit)" }
