entries[335931] = { ["name"] = "Banner des Eroberers", ["text"] = "Pakt-Fähigkeit\nSofort\nErhebt das Banner des Eroberers, was Euch und Euren 2 nächsten Verbündeten 1550 Meisterschaft und um 30% erhöhte Bewegungsgeschwindigkeit gewährt sowie verhindert, dass die Bewegungsgeschwindigkeit unter 100% verringert wird. Hält 15 Sek. lang an.\n\nErzeugt 4 Wut pro Sekunde." }
entries[335932] = { ["name"] = "Todeschakram", ["text"] = "Pakt-Fähigkeit\nSofort\nWirft ein tödliches Chakram auf Euer aktuelles Ziel, das rasch 7-mal (31.6% der Angriffskraft) Schattenschaden verursacht und auf weitere Ziele in der Nähe überspringt. Von 'Todeschakram' getroffene Ziele erleiden 10 Sek. lang 10% mehr körperlichen Schaden durch Euch und Eure Begleiter.\n\nJedes Mal, wenn das Chakram Schaden verursacht, wird sein Schaden um 15% erhöht und Ihr erzeugt 3 Fokus." }
entries[335933] = { ["name"] = "Monströse Gliedmaße", ["text"] = "Pakt-Fähigkeit\nSofort\nFrost\nLässt eine zusätzliche Gliedmaße wachsen, die allen Gegnern in der Nähe im Verlauf von 12 Sek. [(28.4% der Angriffskraft) * 13] Schattenschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Alle 1 Sek. wird ein Gegner zu Eurer Position gezogen, wenn er weiter als 8 Meter von Euch entfernt ist. Die monströse Gliedmaße kann denselben Gegner nur einmal alle 4 Sek. heranziehen.\n\nVerleiht Euch sofort 'Raureif' und erneut alle 6 Sek. danach.\n\nUnheilig\nLässt eine zusätzliche Gliedmaße wachsen, die allen Gegnern in der Nähe im Verlauf von 12 Sek. [(28.4% der Angriffskraft) * 13] Schattenschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Alle 1 Sek. wird ein Gegner zu Eurer Position gezogen, wenn er weiter als 8 Meter von Euch entfernt ist. Die monströse Gliedmaße kann denselben Gegner nur einmal alle 4 Sek. heranziehen.\n\nVerleiht Euch sofort 'Runenverderbnis' und erneut alle 6 Sek. danach.\n\nBlut\nLässt eine zusätzliche Gliedmaße wachsen, die allen Gegnern in der Nähe im Verlauf von 12 Sek. [(28.4% der Angriffskraft) * 13] Schattenschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Alle 1 Sek. wird ein Gegner zu Eurer Position gezogen, wenn er weiter als 8 Meter von Euch entfernt ist. Die monströse Gliedmaße kann denselben Gegner nur einmal alle 4 Sek. heranziehen.\n\nVerleiht Euch sofort 3 Aufladungen von 'Knochenschild' und erneut alle 6 Sek. danach." }
entries[335934] = { ["name"] = "Futter für die Flamme", ["text"] = "Pakt-Fähigkeit\nSofort\nEure Schaden verursachenden Fähigkeiten haben eine Chance, für 25 Sek. einen Dämon aus dem Theater der Schmerzen herbeizurufen. 'Gleve werfen' fügt dem Dämon tödlichen Schaden zu. Beim Tod explodiert er, fügt Gegnern in der Nähe (192.5% der Angriffskraft) Schatten schaden zu und heilt Euch um 20% Eurer maximalen Gesundheit. Die Explosion fügt Zielen über 5 Ziele hinaus verringerten Schaden zu." }
entries[335935] = { ["name"] = "Adaptiver Schwarm", ["text"] = "Pakt-Fähigkeit\nSofort\nBefehligt einen Schwarm, der im Verlauf von 12 Sek. ein Ziel um (157.5% der Zaubermacht) Gesundheit heilt oder ihm (150% der Zaubermacht) Schattenschaden zufügt und die Effektivität Eurer regelmäßigen Effekte beim Ziel um 25% erhöht.\n\nBei Ablauf sucht sich der Schwarm bis zu 3-mal ein neues Ziel, wobei er versucht, abwechselnd zwischen einem Verbündeten und einem Gegner überzuspringen." }
entries[335936] = { ["name"] = "Todesgeboren", ["text"] = "Pakt-Fähigkeit\nSofort\nVerwandelt Euch für 25 Sek. in einen mächtigen Skelettmagier.\n\nWährend Ihr in der Gestalt des Skelettmagiers seid, treffen Eure Fähigkeiten 'Frostblitz', 'Feuerball' und 'Arkanschlag' bis zu 2 Gegner in der Nähe Eures Ziels und Euer Zauberschaden ist um 15% erhöht." }
entries[335937] = { ["name"] = "Knochenstaubgebräu", ["text"] = "Pakt-Fähigkeit\nSofort\nSchleudert ein aus den Knochen Eurer Gegner hergestelltes Gebräu auf den Boden, das alle getroffenen Ziele für 10 Sek. bedeckt. Eure Fähigkeiten haben eine Chance von 50%, sich mit 40% Effektivität ein zweites Mal als Schattenschaden oder Heilung auf das Ziel auszuwirken.\n\n[ Nebelwirker : 'Nebelschwall' heilt alle Ziele, bei denen Euer Knochenstaubgebräu aktiv ist, um zusätzlich (42% der Angriffskraft) Gesundheit / Braumeister : 'Tigerklaue' und 'Fasshieb' verringern die Abklingzeiten Eurer Gebräue um zusätzlich 1 Sek., wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist / Windläufer : 'Wirbelnder Kranichtritt' erstattet 1 Chi, wenn Ihr Gegner angreift, bei denen Euer Knochenstaubgebräu aktiv ist ]" }
entries[335938] = { ["name"] = "Gefrierender Impuls", ["text"] = "Sofort\nMort stößt alle 5 Sek. Frostschleim aus, der Gegnern innerhalb von 10 Metern 0 Frostschaden zufügt, sie mit 'Gefrierende Gliedmaßen' belegt und einen Bereich von 'Gefrierender Boden' hinterlässt." }
entries[335939] = { ["name"] = "Hammer des Bezwingers", ["text"] = "Pakt-Fähigkeit\nSofort\nWirft einen Hammer auf Euer Ziel, der (136% der Zaubermacht) Schattenschaden verursacht und Euren nächsten Einsatz von [ Vergeltung : 'Urteil des Templers' ermächtigt, sodass automatisch 'Göttlicher Sturm' ] [ Heilig : 'Wort der Herrlichkeit' ermächtigt, sodass automatisch 'Licht der Morgendämmerung' /\n\nSchutz\n'Wort der Herrlichkeit' ermächtigt, sodass automatisch 'Schild der Rechtschaffenen' ] mit 25% höherer Effektivität ausgelöst wird.\n\nErzeugt 1 Heilige Kraft." }
entries[335940] = { ["name"] = "Gezackter Knochenstachel", ["text"] = "Pakt-Fähigkeit\nSofort\nSteckt einen Knochenstachel in das Ziel, der (132% der Angriffskraft) körperlichen Schaden sowie alle 3 Sek. (11% der Angriffskraft) Blutungsschaden verursacht, bis das Ziel stirbt oder den Kampf verlässt.\n\nWenn das Ziel stirbt wird, wird 1 Aufladung erstattet.\n\nGewährt 1 Combopunkt plus 1 weiteren pro aktivem Knochenstachel." }
entries[335941] = { ["name"] = "Urzeitliche Welle", ["text"] = "Pakt-Fähigkeit\nSofort\nWiederherstellung\nÜberzieht Euer Ziel mit einer urzeitlichen Welle, die (65% der Zaubermacht) Schattenschaden verursacht und einen Gegner mit 'Flammenschock' belegt oder einen Verbündeten um (65% der Zaubermacht) Gesundheit heilt und ihn mit 'Springflut' belegt.\n\nEuer nächster Einsatz von 'Welle der Heilung' trifft zusätzlich alle Ziele, die mit Eurem Effekt 'Springflut' belegt sind, und verursacht dabei 60% der normalen Heilung.\n\nVerstärkung\nÜberzieht Euer Ziel mit einer urzeitlichen Welle, die (65% der Zaubermacht) Schattenschaden verursacht und einen Gegner mit 'Flammenschock' belegt oder einen Verbündeten um (65% der Zaubermacht) Gesundheit heilt.\n\nEuer nächster Einsatz von 'Blitzschlag' trifft zusätzlich alle Ziele, die mit Eurem Effekt 'Flammenschock' belegt sind, und verursacht dabei 150% des normalen Schadens.\n\nElementar\nÜberzieht Euer Ziel mit einer urzeitlichen Welle, die (65% der Zaubermacht) Schattenschaden verursacht und einen Gegner mit 'Flammenschock' belegt oder einen Verbündeten um (65% der Zaubermacht) Gesundheit heilt.\n\nEuer nächster Einsatz von 'Lavaeruption' trifft zusätzlich alle Ziele, die mit Eurem Effekt 'Flammenschock' belegt sind, und verursacht dabei 80% des normalen Schadens." }
entries[335942] = { ["name"] = "Dezimierungsblitz", ["text"] = "Pakt-Fähigkeit\nSofort\nDämonologie, Dämonologie (Zerstörungshexenmeister)\nSchleudert Blitze aus dezimierender Magie auf Euer Ziel, die [4 * (34.5% der Zaubermacht)] Schattenschaden verursachen und den Schaden Eurer nächsten 3 Einsätze von 'Dämonenblitz' um 100% erhöhen.\n\nSowohl der Schaden von 'Dezimierungsblitz' als auch der Bonus für 'Dämonenblitz' steigt mit abnehmender Gesundheit Eures Ziels an.\n\nZerstörung, Zerstörung (Dämonologiehexenmeister)\nSchleudert Blitze aus dezimierender Magie auf Euer Ziel, die [4 * (34.5% der Zaubermacht)] Schattenschaden verursachen und den Schaden Eurer nächsten 3 Einsätze von 'Verbrennen' um 100% erhöhen.\n\nSowohl der Schaden von 'Dezimierungsblitz' als auch der Bonus für 'Verbrennen' steigt mit abnehmender Gesundheit Eures Ziels an.\n\nGebrechen\nSchleudert Blitze aus dezimierender Magie auf Euer Ziel, die [4 * (34.5% der Zaubermacht)] Schattenschaden verursachen und den Schaden Eurer nächsten 3 Einsätze von um 100% erhöhen.\n\nSowohl der Schaden von 'Dezimierungsblitz' als auch der Bonus für steigt mit abnehmender Gesundheit Eures Ziels an." }
entries[335944] = { ["name"] = "Finstere Festung", ["text"] = "Sofort\nMystische Rüstung umgibt den Zaubernden und verringert seinen erlittenen Schaden 12 Sek. lang um 5%. Dieser Effekt ist stapelbar." }
entries[335945] = { ["name"] = "Ausrüstung der Gefallenen", ["text"] = "Sofort\nErhöht das Tempo des Zaubernden 12 Sek. lang um 5%. Dieser Effekt ist stapelbar." }
entries[335946] = { ["name"] = "Gefrierende Gliedmaßen", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerringert die Bewegungsgeschwindigkeit des Ziels um 6% und entfernt gegebenenfalls eine Anwendung von ' Instabiles Aufputschmittel '.\n\nBetäubt das Ziel bei 10 Stapeln und fügt ihm 6 Sek. lang alle 1.5 Sek. 5 Frostschaden zu." }
