entries[336005] = { ["name"] = "Ohrenbetäubender Schrei", ["text"] = "200 Meter Reichweite\nSofort\nSchrillschwinge fügt allen Spielercharakteren in ihrem Sichtfeld 29628 Schallschaden sowie 12 Sek. lang alle 2 Sek. zusätzlich 7111 Schallschaden zu. Zusätzlich hinterlassen Spielercharaktere ' Blutiges Sekret ' an ihrer Position." }
entries[336006] = { ["name"] = "Zorn der Königin", ["text"] = "Sofort\nWirft das Fläschchen flüssiges Feuer, das Feuerschaden in Höhe von 5% der Gesundheit verursacht und alle Weidenmonstrositäten innerhalb von 5 Metern um die Einschlagsstelle für 5 Sek. betäubt. Verursacht zusätzlich pro Sekunde Feuerschaden in Höhe von 2% der Gesundheit." }
entries[336007] = { ["name"] = "Schwelender Zorn", ["text"] = "Unbegrenzte Reichweite\nSofort\nAuf dem Schwierigkeitsgrad 'Heroisch' und höher hinterlässt 'Fatale Finesse' eine Kugel flüchtiger Anima, die nach 10 Sek. explodiert und allen Spielercharakteren bis zu 71107 Schattenschaden zufügt.\n\nAlle (7 / 10) Sek. fügt die Kugel Spielercharakteren innerhalb von 3 Metern 4740 Schattenschaden zu, was die Explosion am Ende um denselben Wert verringert." }
entries[336008] = { ["name"] = "Schwelender Zorn", ["text"] = "Unbegrenzte Reichweite\nSofort\nAuf dem Schwierigkeitsgrad 'Heroisch' und höher hinterlässt 'Fatale Finesse' eine Kugel flüchtiger Anima, die nach 10 Sek. explodiert und allen Spielercharakteren bis zu 71107 Schattenschaden zufügt.\n\nAlle (7 / 10) Sek. fügt die Kugel Spielercharakteren innerhalb von 3 Metern 4740 Schattenschaden zu, was die Explosion am Ende um denselben Wert verringert." }
entries[336009] = { ["name"] = "Der Bußfertige", ["text"] = "Sofort\n'Machtwort: Glanz' hat eine Chance von 60%, Euren nächsten Einsatz von 'Sühne' kostenlos zu machen und ihn 3 zusätzliche Geschosse verschießen zu lassen." }
entries[336010] = { ["name"] = "Verstärken", ["text"] = "10 Meter Reichweite\nWirken in 10 sek.\nDrückt die richtigen Knöpfe an diesem Gerät, um den Zauberschutz um Ve'naris Zuflucht zu verstärken.\n\nDrückt keine Knöpfe, von denen Ve'nari nichts gesagt hat." }
entries[336011] = { ["name"] = "Der Bußfertige", ["text"] = "Runenschnitzmacht\n'Machtwort: Glanz' hat eine Chance von 60%, Euren nächsten Einsatz von 'Sühne' kostenlos zu machen und ihn 3 zusätzliche Geschosse verschießen zu lassen.\nRunenschnitzen: Füße, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Priester (Disziplin)" }
