entries[336036] = { ["name"] = "Markzahn", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der unersättliche Appetit von Markzahn, Nachkomme von Knochenzahn, wurde von Amarth dem Ernter geschätzt, auch wenn er die Experimente des sadistischen Kommandanten störte.\"\nBeute:\nNalthor der Eisbinder\nZone:\nDie Nekrotische Schneise (Mythisch)\n\nBeute:\nSchatz des Herausforderers\nZone:\nDie Nekrotische Schneise" }
entries[336037] = { ["name"] = "Schneide des Vergessens", ["text"] = "10 Meter Reichweite\nWirken in 2 sek.\nGreift alle Gegner in einem kegelförmigen Bereich an und verursacht körperlichen Schaden." }
entries[336038] = { ["name"] = "Kahler Fledderflügel", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Fledderflügel sind notwendig für den Kreislauf des Lebens in den Schattenlanden. In der rauen Umgebung von Maldraxxus sind sie sowohl Räuber als auch Beute.\"\nZone:\nMaldraxxus" }
entries[336039] = { ["name"] = "Grauenhafter Fledderflügel", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Fledderflügel von Maldraxxus werden für ihre Fähigkeit, mühelos in den Himmel der Schattenlande aufzusteigen, sehr geschätzt. Ihre Reiter sind dadurch in der Lage, ihre Verbündeten aus der Luft zu unterstützen oder ihre Gegner von oben aus zu überrumpeln.\"\nPaktfeature:\nDer Gluthof\nPakt:\nVenthyr\n\nPaktfeature:\nKonservatorium der Königin\nPakt:\nNachtfae\n\nPaktfeature:\nPfad des Aufstiegs\nPakt:\nKyrianer\n\nPaktfeature:\nMonstrositätenfabrik\nPakt:\nNekrolords" }
entries[336040] = { ["name"] = "Herzpilzblähungen", ["text"] = "Sofort\nDurch den Verzehr eines Herzpilzes von Blähungen geplagt, was die Bewegungsgeschwindigkeit 5 Sek. lang um 65% verringert." }
entries[336041] = { ["name"] = "Knochenvernähter Fleischroc", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Nur erfahrene Fleischnäher, die ihre meisterhafte Beherrschung der Magien von Maldraxxus unter Beweis gestellt haben, sind mächtig genug, einen Todesroc dieser Größe zu erschaffen.\"\nBeruf:\nMonstrositätenflickerei\nZone:\nMaldraxxus" }
entries[336042] = { ["name"] = "Bulliger Todesroc", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Todesrocs sind Monstrositäten, zusammengeflickt aus Eingeweiden, Knochen und Organen, die nicht zum Bau von Soldaten im Haus der Konstrukte gebraucht wurden.\"\nBeute von:\nVioletter Fehler\nZone:\nMaldraxxus" }
entries[336043] = { ["name"] = "Geistpilzschwindel", ["text"] = "Sofort\nLeidet durch den Verzehr eines Geistpilzes an Schwindel, was die Trefferchance 4 Sek. lang um 50% verringert." }
entries[336044] = { ["name"] = "Flinkpilzkrankheit", ["text"] = "Sofort\nMagenkrank durch den Verzehr eines Flinkpilzes, was Euch für 3 Sek. betäubt." }
entries[336045] = { ["name"] = "Räuberischer Seuchenroc", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Giegers unstillbarer Hunger ist im Haus der Konstrukte legendär, und kein Tier ist zu groß oder zu knochig, um in seinen riesigen Magen zu passen.\"\nBeute von:\nGieger\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
entries[336046] = { ["name"] = "Eisiger Stoß" }
entries[336047] = { ["name"] = "Eisiger Stoß", ["text"] = "100 Meter Reichweite\nWirken in 3.5 sek. 6 sek. Abklingzeit\nEine Eiswelle schlägt über Spielercharaktere in einer Linie vor dem Zaubernden hinweg, verursacht beim Einschlag 25 Frostschaden und stößt Gegner zurück." }
entries[336048] = { ["name"] = "Kritischer Schuss", ["text"] = "30 Meter Reichweite\nWirken in 2 sek. 3 sek. Abklingzeit\nSchießt auf einen Gegner, verursacht schweren körperlichen Schaden und ignoriert Rüstung." }
entries[336051] = { ["name"] = "Pustulöser Ausstoß", ["text"] = "Sofort\nImer stößt Schleim aus, der Spielercharakteren innerhalb von 12 Metern 3 Naturschaden zufügt, sie mit 'Seuchenfieber' belegt und mehrfach 'Pustulöse Lache' erzeugt.\n\n'Pustulöser Ausstoß' fügt Gegnern innerhalb von 7 Metern um den Einschlag 10 Naturschaden zu.\n\nDer Einschlag erschafft einen Bereich von 'Pustulöse Lache', der Spielercharakteren im Effektbereich 10s2 Naturschaden zufügt und sie mit 'Seuchenfieber' belegt." }
entries[336052] = { ["name"] = "Pustulöser Ausstoß", ["text"] = "40 Meter Reichweite\nSofort\nImer stößt Schleim aus, der Spielercharakteren innerhalb von 12 Metern 3 Naturschaden zufügt, sie mit 'Seuchenfieber' belegt und mehrfach 'Pustulöse Lache' erzeugt.\n\n'Pustulöser Ausstoß' fügt Gegnern innerhalb von 7 Metern um den Einschlag 10 Naturschaden zu.\n\nDer Einschlag erschafft einen Bereich von 'Pustulöse Lache', der Spielercharakteren im Effektbereich 10s2 Naturschaden zufügt und sie mit 'Seuchenfieber' belegt." }
