entries[336063] = { ["name"] = "Lavarückstrom des Windsprechers", ["text"] = "Runenschnitzmacht\nWenn Ihr 'Erdschock' einsetzt, erhaltet Ihr 'Lavasog' und der Schaden Eures nächsten Einsatzes von 'Lavaeruption' wird um 20% erhöht.\nRunenschnitzen: Füße, Rücken\nQuelle: Weltbossbeute: Valinor, das Licht der Äonen\nBenötigt: Schamane (Elementar)" }
entries[336064] = { ["name"] = "Unbeirrbarer Abendläufer", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Der Pfad des Aufstiegs ist eine anspruchsvolle Prüfung und wer alle Eigenschaften unter Beweis stellt, die die Kyrianer schätzen, soll seinen rechtmäßigen Lohn erhalten.\"\nPaktfeature:\nDer Gluthof\nPakt:\nVenthyr\n\nPaktfeature:\nKonservatorium der Königin\nPakt:\nNachtfae\n\nPaktfeature:\nPfad des Aufstiegs\nPakt:\nKyrianer\n\nPaktfeature:\nMonstrositätenfabrik\nPakt:\nNekrolords" }
entries[336065] = { ["name"] = "Lavarückstrom des Windsprechers", ["text"] = "Sofort\nWenn Ihr 'Erdschock' einsetzt, erhaltet Ihr 'Lavasog' und der Schaden Eures nächsten Einsatzes von 'Lavaeruption' wird um 20% erhöht." }
