entries[336067] = { ["name"] = "Klarheit der Gedanken", ["text"] = "Runenschnitzmacht\n[ Geisthülle : 'Geisthülle' erhöht die Dauer bestehender Effekte von 'Abbitte' um 3 Sek. und verringert die Manakosten von Schadenszaubern um 30% / Während 'Euphorie' aktiv ist, kostet 'Machtwort: Schild' 20% weniger Mana und der damit angewendete Effekt 'Abbitte' hält 6 Sek. länger an.](Procchance: 50%)\nRunenschnitzen: Brust, Finger\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Priester (Disziplin)" }
entries[336068] = { ["name"] = "Fokussierter Blick", ["text"] = "20 Meter Reichweite\nWirken in 1 sek.\nInflicts Shadow damage to an enemy every 1 sec for 6 Sek.." }
entries[336069] = { ["name"] = "Reflektierende Wolke", ["text"] = "Sofort\nReagenzien:\nVerzauberter Spiegelstaub\nNach Erhalt: Eine Glaswolke umgibt Euch und gewährt Euch eine Chance von 25%, 20% eines Zaubers auf den Zaubernden zu reflektieren. Hält 30 Min. lang an. Kann nur im Freien in den Schattenlanden verwendet werden." }
